SELECT ?s ?ts WHERE {
  ?s brick:hasLocation ?loc .
  ?s rdf:type brick:ElectricPowerSensor .
  ?loc rdf:type brick:Zone .
  FILTER (str(?loc) LIKE '%ZN%' AND (str(?loc) LIKE '%Core_ZN%' OR str(?loc) LIKE '%Perimeter_ZN_3%'))
  OPTIONAL { ?s ref:hasTimeseriesId ?ts }
}

SELECT ?s ?loc ?ts WHERE {
  ?s rdf:type brick:ElectricPowerSensor .
  ?s brick:hasLocation ?loc .
  FILTER (str(?loc) LIKE '%Core_ZN%' OR str(?loc) LIKE '%Perimeter_ZN_3%')
  OPTIONAL { ?s ref:hasTimeseriesId ?ts }
}

SELECT ?s ?loc ?ts WHERE {
  ?s rdf:type brick:ElectricPowerSensor .
  ?s brick:hasLocation ?loc .
  OPTIONAL { ?s ref:hasTimeseriesId ?ts }
}

SELECT ?s ?p ?o WHERE {
  ?s brick:isTypeOf* brick:ElectricPowerSensor .
  OPTIONAL { ?s brick:hasLocation ?o }
} LIMIT 50

SELECT ?s ?type WHERE {
  ?s rdf:type ?type .
  FILTER (str(?type) LIKE '%Power%')
} LIMIT 50

SELECT ?s ?loc ?ts ?lbl WHERE {
  ?s rdf:type ?t .
  OPTIONAL { ?s rdfs:label ?lbl }
  FILTER (CONTAINS(str(?t), "ElectricPowerSensor") || CONTAINS(str(?t), "Electric_Power"))
} LIMIT 50

SELECT ?s ?t WHERE {
  ?s rdf:type ?t .
  FILTER (CONTAINS(str(?t), "Zone") || CONTAINS(str(?t), "Room") || CONTAINS(str(?t), "Space"))
  FILTER (!CONTAINS(str(?t), "Temperature") && !CONTAINS(str(?t), "Setpoint") && !CONTAINS(str(?t), "Sensor"))
} LIMIT 50

